mapper.select:
select answer_id, survey_id, submit_ip, submit_ua, submit_time, cost_ms, channel_code, client_token,
       coalesce(valid_flag, '1') as valid_flag, remark
from biz_survey_answer

    and survey_id = #{surveyId}
    and channel_code = #{channelCode}
    and submit_ip like concat('%', #{submitIp}, '%')
    and coalesce(valid_flag, '1') = #{validFlag}

        and to_char(submit_time, 'YYYYMMDD') >= to_char(#{params.beginTime}::timestamp, 'YYYYMMDD')


        and to_char(submit_time, 'YYYYMMDD') <= to_char(#{params.endTime}::timestamp, 'YYYYMMDD')


order by answer_id desc

select answer_id, survey_id, submit_ip, submit_ua, submit_time, cost_ms, channel_code, client_token,
       coalesce(valid_flag, '1') as valid_flag, remark
from biz_survey_answer where answer_id = #{answerId}

mapper.update:
update biz_survey_answer
valid_flag = #{validFlag}, remark = #{remark},
where answer_id = #{answerId}

mapper.select:
select count(1) from biz_survey_answer
where survey_id = #{surveyId}
  and submit_time >= date_trunc('day', now())
